mapper.select:
select u.username,u.avatar,u.introduction,
u.vip_expire_time, p.id as postId, p.title, p.content, p.create_time,
p.like_count, p.comment_count,p.user_id
from community_post p
left join user u on p.user_id=u.id

   p.is_deleted=0

       and  p.user_id=#{userId}



        AND (
        p.title LIKE #{postkey}
        OR p.content LIKE  #{postkey}
        OR u.username LIKE  #{postkey}
        )


        and p.id < #{lastId}


order by p.create_time desc
limit #{pageSize}

select count(1)>0
from community_post p
left join user u on p.user_id=u.id
where p.is_deleted=0

        and  p.user_id= #{userId}



        AND (p.title LIKE #{postkey}
        OR p.content LIKE  #{postkey}
        OR u.username LIKE  #{postkey})


        and p.id < #{lastId}

limit 1

select count(*)>0
from like_record
where user_id=#{userId}
and target_id=#{postId}
and target_type=3
and is_canceled=0

select count(*)>0
from user_follow
where user_id=#{userId}
and followed_user_id= #{authorId}
